$ErrorActionPreference='Stop'
New-Item -ItemType Directory -Force -Path C:\le | Out-Null
[IO.File]::WriteAllBytes('C:\le\src.zip',[Convert]::FromBase64String(''))
if(Test-Path C:\le\src){Remove-Item -Recurse -Force C:\le\src}
Expand-Archive -Path C:\le\src.zip -DestinationPath C:\le -Force
New-Item -ItemType Directory -Force -Path C:\le\artifacts | Out-Null
[IO.File]::WriteAllBytes('C:\le\artifacts\run-x86-matrix.ps1',[Convert]::FromBase64String(''))
$env:DOTNET_ROOT='C:\dotnet'
$env:PATH="C:\dotnet;$env:PATH"
Set-Location C:\le
dotnet build src\LightEpoch.Repro -c Release --nologo
